-- Ověřená studentská místa pro Brno, Prahu, Olomouc a Ostravu.
-- Souřadnice vycházejí z oficiálních adres a byly ověřeny přes Nominatim/OSM.
-- Opakované spuštění je idempotentní; ruční textové úpravy existujících řádků se nepřepisují.

alter table public.places
  add column if not exists subcategory text,
  add column if not exists access_type text check (access_type is null or access_type in ('public','student','registered','mixed')),
  add column if not exists isic_required boolean,
  add column if not exists library_card_required boolean,
  add column if not exists registration_required boolean,
  add column if not exists reservation_url text check (reservation_url is null or reservation_url ~ '^https://'),
  add column if not exists opening_exceptions text,
  add column if not exists eduroam_available boolean,
  add column if not exists computers_available boolean,
  add column if not exists printing_available boolean,
  add column if not exists copying_available boolean,
  add column if not exists scanning_available boolean,
  add column if not exists study_mode text check (study_mode is null or study_mode in ('quiet','group','mixed','none')),
  add column if not exists reservable boolean,
  add column if not exists evening_access boolean,
  add column if not exists nonstop_access boolean,
  add column if not exists temporary_status text check (temporary_status is null or temporary_status in ('open','limited','temporarily_closed')),
  add column if not exists source_etag text,
  add column if not exists source_last_modified text,
  add column if not exists source_content_hash text check (source_content_hash is null or source_content_hash ~ '^[a-f0-9]{64}$');

create index if not exists places_public_city_category_subcategory_idx
  on public.places(city_id,category,subcategory,name)
  where status='approved' and is_demo=false and verification_status='verified';
create index if not exists places_public_viewport_idx
  on public.places(city_id,latitude,longitude,category)
  where status='approved' and is_demo=false and verification_status='verified';

grant select (subcategory,access_type,isic_required,library_card_required,registration_required,reservation_url,opening_exceptions,eduroam_available,computers_available,printing_available,copying_available,scanning_available,study_mode,reservable,evening_access,nonstop_access,temporary_status)
  on public.places to anon, authenticated;

