  $json$::jsonb) as p(
    id text, city text, name text, category text, subcategory text, description text,
    address text, lat numeric, lng numeric, hours text, source text, university text,
    faculty text, access text, public_access boolean, student_only boolean,
    access_type text, isic_required boolean, library_card_required boolean,
    registration_required boolean, study_mode text, wifi boolean, eduroam boolean,
    outlets boolean, computers boolean, printing boolean, copying boolean, scanning boolean,
    reservable boolean, evening boolean, nonstop boolean, temporary_status text,
    opening_exceptions text, accessibility text
  )
)
insert into public.places (
  id,city_id,name,category,subcategory,description,why_visit,address,latitude,longitude,
  opening_hours,website_url,source_url,last_verified_at,opening_hours_verified_at,
  verification_status,source_sync_status,source_checked_at,status,is_demo,access_conditions,
  university_id,faculty_id,origin,study_suitable,wifi_available,eduroam_available,
  outlets_available,computers_available,printing_available,copying_available,scanning_available,
  public_access,student_only,access_type,isic_required,library_card_required,registration_required,
  study_mode,reservable,evening_access,nonstop_access,temporary_status,opening_exceptions,
  accessibility,source_license,source_external_id,source_dataset_updated_at
)
select
  id::uuid,city,name,category::public.place_category,subcategory,description,
  case when category='student_service' then 'Praktická podpora při studiu.' else 'Ověřené místo pro studium, práci s odbornými zdroji nebo klidný pobyt.' end,
  address,lat,lng,hours,source,source,'2026-10-07 12:00:00+02'::timestamptz,
  case when hours is not null then '2026-10-07 12:00:00+02'::timestamptz end,
  'verified','verified','2026-10-07 12:00:00+02'::timestamptz,'approved',false,access,
  university,faculty,'official',category in ('library','study_room','student_service'),wifi,eduroam,
  outlets,computers,printing,copying,scanning,public_access,student_only,access_type,
  isic_required,library_card_required,registration_required,study_mode,reservable,evening,nonstop,
  coalesce(temporary_status,'open'),opening_exceptions,accessibility,
  'Oficiální veřejný web provozovatele; poloha ověřena pomocí OpenStreetMap',
  'official-place:' || city || ':' || regexp_replace(lower(name),'[^a-z0-9]+','-','g'),
  '2026-10-07 12:00:00+02'::timestamptz
from seed
on conflict (id) do update set
  source_url=excluded.source_url,
  website_url=excluded.website_url,
  last_verified_at=excluded.last_verified_at,
  source_checked_at=excluded.source_checked_at,
  verification_status='verified',
  source_sync_status='verified',
  subcategory=coalesce(public.places.subcategory,excluded.subcategory),
  access_type=coalesce(public.places.access_type,excluded.access_type),
  study_mode=coalesce(public.places.study_mode,excluded.study_mode),
  source_dataset_updated_at=excluded.source_dataset_updated_at;

-- Dvě dříve založené kopie byly v produkci potvrzeny jako stejné provozovny.
-- Zachováváme jejich historii, ale v katalogu ponecháváme pouze bohatší ověřený záznam.
update public.places set status='archived', updated_at=now()
where id in (
  '52222222-2222-4222-8222-222222222226'::uuid,
  '52222222-2222-4222-8222-222222222227'::uuid
) and city_id='brno' and status='approved';
